import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import { useNavigate } from "react-router-dom";
import Popup from "./Popup";
import axios from "axios";
import { Group } from "../Model/Group.model";
import "./styles/Groups.scss";
import GroupNavBar from "./GroupNavBar";
import { APIService } from "../api/requests";
import {
  Button,
  Checkbox,
  Container,
  createTheme,
  Flex,
  MantineProvider,
  Paper,
} from "@mantine/core";

function Groups() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState<Group[]>([]);
  const [showPopup, setShowPopup] = useState<boolean>(false);

  const theme = createTheme({
    cursorType: "pointer",
  });

  useEffect(() => {
    axios
      .get<Group[]>(`http://localhost:5257/api/Group/`)
      .then((response) => {
        setGroups(response.data);
        console.log(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const openGroup = (event: any, groupId: string) => {
    event?.stopPropagation();
    navigate(`/group/${groupId}`);
  };
  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const onCreate = (value: string) => {
    // axios
    //   .post<Group>("http://localhost:5257/api/Group", { name: value })
    //   .then((response) => {
    //     setGroups((old) => [...old, response.data]);
    //   })
    //   .catch((error) => {
    //     alert("Name cannot be empty");
    //   });
    APIService.group.postGroup({ name: value }).then((response) => {
      setGroups((old) => [...old, response.data]);
    });
  };

  const checkHandler = (idToUpdate: string, checked: boolean) => {
    const group = groups.find((x) => x.id === idToUpdate);
    if (group != null) {
      setGroups((group) =>
        group.map((x) =>
          x.id === idToUpdate ? { ...x, isChecked: !checked } : x
        )
      );
    }
  };
  return (
    <>
      <Paper shadow="xs">
        <GroupNavBar />
      </Paper>
      <Container size="lg" w="90%">
        <Flex
          bg="white"
          justify="space-between"
          align="center"
          pt="xs"
          pb="xs"
          p="sm"
          style={{ borderTopLeftRadius: "20px", borderTopRightRadius: "20px" }}
          mt="md"
        >
          <div>
            <MantineProvider theme={theme}>
              <Checkbox size="sm" label="Select All"></Checkbox>
            </MantineProvider>
          </div>

          <div>
            {/* <button className="btn btn-outline-danger btn-sm me-2">
              Delete Selected
            </button> */}
            <Button>Delete Selected</Button>
          </div>
        </Flex>
        {/* Group section */}
        <section className="d-flex align-content-start bg-white p-2 rounded-bottom-4 shadow">
          <input
            type="checkbox"
            name=""
            className="form-check-input me-2"
            id=""
          />
          {/* <GroupsIcon fontSize="large" className="mb-3 me-3" color="primary" /> */}
          <div className="d-flex flex-column justify-content-between">
            <div className="d-flex fw-semibold">Group</div>
            <div className="small text-muted">
              24 members •<span className="text-danger">Owe: $2,450</span> •
              <span className="text-success">Owed: $3,800</span> • Created on
              June 12, 2025
            </div>
          </div>

          <div className="d-flex align-items-end justify-content-end ms-auto p-2"></div>
        </section>
      </Container>
    </>
  );
}

export default Groups;
